window.RP_SESSION={"id":"S-8aeef08583d2","messages":[{"id":"RP-III-0130436","time":"2026-07-28T01:47:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"슥슥, 챱챱.","characters":["P-c93f55c91873"]},{"id":"RP-III-0130437","time":"2026-07-28T01:47:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"쓱쓱, 츠르륵.","characters":["P-c93f55c91873"]},{"id":"RP-III-0130438","time":"2026-07-28T01:47:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"싹싹싹, 챱챱.","characters":["P-c93f55c91873"]},{"id":"RP-III-0130439","time":"2026-07-28T01:48:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"흠?\"\n\n빗자루질을 하다가 도서관 앞에 멈춰선 델타인. 이미 도서관에 있는 책들은 몽땅 읽어버렸지만… 오늘은 뭔가 다릅니다.","characters":["P-c93f55c91873"]},{"id":"RP-III-0130440","time":"2026-07-28T01:52:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"또 환각을 본 걸까요?","characters":["P-c93f55c91873"]},{"id":"RP-III-0130441","time":"2026-07-28T01:53:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"흐린 달빛 아래, 인간을 닮은 괴물이 모습을 드러내었습니다. 쪼그려 앉아 있는 괴물은 그야말로 끔찍한 외양을 갖추고 있었습니다.\n\n벌거벗은 전신엔 검은 비늘이 덮여 있었고, 사지엔 갈고리처럼 길고 날카로운 손발톱이 달려 있었습니다. \n\n황소의 그것만큼 두껍고 날카로운 뿔을 단 채 도마뱀의 그것만큼 길고 유연한 꼬리를 천천히 살랑거립니다. 세로 동공엔 샛노란 안광이 넘실대었습니다.","characters":["P-c93f55c91873"]},{"id":"RP-III-0130442","time":"2026-07-28T01:54:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"흐-\"\n\n톱날 같은 이빨이 빼곡하게 들어찬 아가리가 긴 호선을 그렸습니다. 그리고 델타인은…….\n\n\"엥.\"","characters":["P-c93f55c91873"]},{"id":"RP-III-0130443","time":"2026-07-28T01:54:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"너 니콜라스냐? 이야, 멋있어졌는데 임마?\"","characters":["P-c93f55c91873"]},{"id":"RP-III-0130444","time":"2026-07-28T01:55:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"꿈만 같은 일이야. 우리가 이렇게 마주 보고 대화를 나누다니. 정말 꿈만 같아.\"\n\n차갑지만 어쩐지 익숙하게 느껴지는 목소리. 다시 보니 괴물의 외양 역시 낯설지가 않았습니다. \n\n비늘이나 꼬리 따위는 영락없는 파충류의 그것이었지만, 이목구비나 체형이 눈에 익군요.","characters":["P-c93f55c91873"]},{"id":"RP-III-0130445","time":"2026-07-28T01:57:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"아, 알았다…!\"","characters":["P-c93f55c91873"]},{"id":"RP-III-0130446","time":"2026-07-28T01:57:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"너, 데이지인 척하던 식인 악마로구나!\"\n\n델타인이 제 무릎을 탁 쳤습니다.","characters":["P-c93f55c91873"]},{"id":"RP-III-0130447","time":"2026-07-28T01:58:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"이 사람 씹어먹는 빌어먹을 녀석, 이 어둠대왕께서 오늘 네 어미와 아비까지 모조리 두들겨패서 버릇을 고쳐놔주마!\"","characters":["P-c93f55c91873"]},{"id":"RP-III-0130448","time":"2026-07-28T01:58:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"!어둠","characters":["P-c93f55c91873"]},{"id":"RP-III-0130449","time":"2026-07-28T01:58:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 어둠 판정 :\n[1, 5, 4] + [5, 6, 4]\n성공수 : [ 5 ]","characters":[]},{"id":"RP-III-0130450","time":"2026-07-28T02:10:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"선고(宣告)!\"\n\n통나무도 우습게 베어낼 절삭력을 지닌 검은 참격이 연꽃이 개화하듯 델타인을 중심으로 뻗어 나갑니다. \n\n슈카카칵!\n\n참격을 얻어맞은 책상과 책들이 동사한 짐승과 사람처럼 꽁꽁 얼어붙어서, 어두운 빛깔의 성에가 낀 채로 바스라집니다.","characters":["P-c93f55c91873"]},{"id":"RP-III-0130451","time":"2026-07-28T02:10:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"흠, 이 자식이 도망을 갔네.\"","characters":["P-c93f55c91873"]},{"id":"RP-III-0130452","time":"2026-07-28T02:12:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"혼자서 중얼거린 델타인의 말대로, 괴물딱지가 쭈그려 앉아있던 자리엔 그 어떤 흔적도 남아있지 않습니다….","characters":["P-c93f55c91873"]},{"id":"RP-III-0130453","time":"2026-07-28T02:12:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"에이, 뭐. 청소하다 마주치겠지.\"","characters":["P-c93f55c91873"]},{"id":"RP-III-0130454","time":"2026-07-28T02:12:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"메리 록 누님이랑 야식이나 먹어야겠다.\"","characters":["P-c93f55c91873"]},{"id":"RP-III-0130455","time":"2026-07-28T02:12:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"…오, 니콜라스랑 데이지도 부를까?\"","characters":["P-c93f55c91873"]},{"id":"RP-III-0130456","time":"2026-07-28T02:12:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"…아예 내 친구들과의 정기적 모임을 만들어버려?\"","characters":["P-c93f55c91873"]},{"id":"RP-III-0130457","time":"2026-07-28T02:13:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"\"……아예 내 하수인 후보자들끼리 경연을 펼치게 할까?\"","characters":["P-c93f55c91873"]},{"id":"RP-III-0130458","time":"2026-07-28T02:13:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"델타인이 잡소리를 내뱉으면서, 길드의 밤은 깊어져만 갑니다.","characters":["P-c93f55c91873"]},{"id":"RP-III-0130459","time":"2026-07-28T02:13:00+09:00","room":"RP III","name":"델타인 / 정체 미상의 괴물","profile":"션","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c93f55c91873"]},{"id":"RP-III-0130460","time":"2026-07-28T02:13:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
